import{_ as p,a0 as n,w as d,s as l,ao as r,I as i,x as e,a1 as a,A as o}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const x=JSON.parse('{"title":"入门：如何在 Fedora Linux 中切换到深色模式 | LCTT x X-CMD","titleTemplate":false,"description":"入门：如何在 Fedora Linux 中切换到深色模式 | LCTT (202111) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"入门：如何在 Fedora Linux 中切换到深色模式 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"入门：如何在 Fedora Linux 中切换到深色模式 | LCTT (202111) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202111/20211113 How to Switch to Dark Mode in Fedora Linux -Beginner-s Tip","title":"入门：如何在 Fedora Linux 中切换到深色模式","tag":"202111","desc":""},"relativePath":"202111/20211113 How to Switch to Dark Mode in Fedora Linux -Beginner-s Tip.md","filePath":"[post].md"}'),m={name:"202111/20211113 How to Switch to Dark Mode in Fedora Linux -Beginner-s Tip.md"};function u(g,t,h,f,k,w){const s=n("Link");return d(),l("div",null,[t[18]||(t[18]=r('<h1 id="入门-如何在-fedora-linux-中切换到深色模式" tabindex="-1">入门：如何在 Fedora Linux 中切换到深色模式 <a class="header-anchor" href="#入门-如何在-fedora-linux-中切换到深色模式" aria-label="Permalink to “入门：如何在 Fedora Linux 中切换到深色模式”">​</a></h1><p><img src="https://img.linux.net.cn/data/attachment/album/202111/20/114412oqqw4mdnxbwfbprb.jpg" alt=""></p><p>与 Ubuntu 不同，Fedora 提供的是真正的、原生般的 GNOME 体验，而且体验很好，横向布局、三指滑动，一切都很好。</p><p>我不喜欢的一点是默认的标准主题，它是 Adwaita Light（默认）主题和深色的 GNOME Shell 的混合体。</p><p>因此，虽然通知和通知区是深色的，但系统和应用的其他部分是浅色主题。老实说，对我来说，这看起来很不协调。</p><p><img src="https://i0.wp.com/itsfoss.com/wp-content/uploads/2021/11/fedora-gnome-standard-theme.webp?resize=800%2C450&amp;ssl=1" alt="Fedora GNOME standard theme"></p><p>另一方面，深色主题让它看起来更好。</p><p><img src="https://i2.wp.com/itsfoss.com/wp-content/uploads/2021/11/fedora-gnome-dark-theme.webp?resize=800%2C450&amp;ssl=1" alt="Fedora GNOME dark theme"></p><p>让我告诉你如何在 Fedora 或其他任何使用 GNOME 桌面环境的发行版中开启深色模式。</p><h3 id="在-fedora-中切换到深色模式" tabindex="-1">在 Fedora 中切换到深色模式 <a class="header-anchor" href="#在-fedora-中切换到深色模式" aria-label="Permalink to “在 Fedora 中切换到深色模式”">​</a></h3><p>好了！我将分享命令行的方法，因为它更快。打开一个终端，使用这个命令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>gsettings set org.gnome.desktop.interface gtk-theme Adwaita-dark</span></span></code></pre></div><p>完成了。这很容易，对吗？但我也要展示一下 GUI 的方法。</p><p>因为我主要使用 Ubuntu，所以我始终参照 Ubuntu。Ubuntu 在系统设置中本身就提供了在浅色和深色主题之间切换的选项。</p>',14)),i("p",null,[t[1]||(t[1]=e("然而，在原生 GNOME 中却没有这样的设置。你必须先 ",-1)),a(s,{href:"https://itsfoss.com/install-gnome-tweaks-fedora/"},{default:o(()=>[...t[0]||(t[0]=[e("在 Fedora 上安装 GNOME Tweaks 工具",-1)])]),_:1}),t[2]||(t[2]=e("，然后用它来切换主题。",-1))]),t[19]||(t[19]=r('<p>你可以在软件中心搜索它并点击“<ruby>安装<rt>Install</rt></ruby>”按钮：</p><p><img src="https://i1.wp.com/itsfoss.com/wp-content/uploads/2021/11/install-gnome-tweaks-fedora.webp?resize=800%2C448&amp;ssl=1" alt="Install GNOME Tweaks from the software center in Fedora"></p><p>或者，你在终端输入以下命令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo dnf install gnome-tweaks</span></span></code></pre></div><p>安装完成后，按 <code>Super</code> 键（<code>Windows</code> 键）在系统菜单中搜索它：</p><p><img src="https://i0.wp.com/itsfoss.com/wp-content/uploads/2021/11/start-gnome-tweaks-tool-in-Fedora.png?resize=800%2C271&amp;ssl=1" alt="Start GNOME Tweaks"></p><p>点击左侧边栏的“<ruby>外观<rt>Appearance</rt></ruby>”标签，点击主题部分下的应用。</p><p><img src="https://i0.wp.com/itsfoss.com/wp-content/uploads/2021/11/change-GTK-theme-Fedora.webp?resize=800%2C532&amp;ssl=1" alt="Changing theme in Fedora"></p><p>你会看到这里有几个可用的主题。你应该在这里选择 “Adwaita-dark”。当你选择了它，应用就会切换到深色主题。</p><p><img src="https://i0.wp.com/itsfoss.com/wp-content/uploads/2021/11/switching-dark-mode-fedora.png?resize=800%2C515&amp;ssl=1" alt="Selecting the Adwaita-dark theme"></p><p>就是你在 Fedora 中切换到深色模式所需要做的一切。由于 GNOME Shell 已经在使用深色主题，你不需要明确地将它设置为深色模式。所有的通知、信息栏等都是在深色模式下的。</p><h3 id="总结" tabindex="-1">总结 <a class="header-anchor" href="#总结" aria-label="Permalink to “总结”">​</a></h3><p>你可以找到各种深色 GTK 主题并安装它们来给你的 Fedora 带来不同的深色外观。然而，我注意到，只有系统自己的深色主题才能被网页浏览器识别。</p><p>所以，如果你访问一个根据你的系统主题自动启用深色模式的网站，它将与 Adwaita-dark 兼容，但可能与其他深色 GTK 主题不兼容。</p><p>这就是使用系统提供的深色主题的一个优势。</p><p>如你所见，在 Fedora 中启用深色模式并不是什么火箭科学。它只是一个了解和发现的过程。</p><p>享受深色色彩吧！</p><hr>',18)),i("p",null,[t[4]||(t[4]=e("via: ",-1)),a(s,{href:"https://itsfoss.com/fedora-dark-mode/"},{default:o(()=>[...t[3]||(t[3]=[e("https://itsfoss.com/fedora-dark-mode/",-1)])]),_:1})]),i("p",null,[t[9]||(t[9]=e("作者：",-1)),a(s,{href:"https://itsfoss.com/author/abhishek/"},{default:o(()=>[...t[5]||(t[5]=[e("Abhishek Prakash",-1)])]),_:1}),t[10]||(t[10]=e(" 选题：",-1)),a(s,{href:"https://github.com/lujun9972"},{default:o(()=>[...t[6]||(t[6]=[e("lujun9972",-1)])]),_:1}),t[11]||(t[11]=e(" 译者：",-1)),a(s,{href:"https://github.com/geekpi"},{default:o(()=>[...t[7]||(t[7]=[e("geekpi",-1)])]),_:1}),t[12]||(t[12]=e(" 校对：",-1)),a(s,{href:"https://github.com/wxy"},{default:o(()=>[...t[8]||(t[8]=[e("wxy",-1)])]),_:1})]),i("p",null,[t[15]||(t[15]=e("本文由 ",-1)),a(s,{href:"https://github.com/LCTT/TranslateProject"},{default:o(()=>[...t[13]||(t[13]=[e("LCTT",-1)])]),_:1}),t[16]||(t[16]=e(" 原创编译，",-1)),a(s,{href:"https://linux.cn/"},{default:o(()=>[...t[14]||(t[14]=[e("Linux中国",-1)])]),_:1}),t[17]||(t[17]=e(" 荣誉推出",-1))])])}const C=p(m,[["render",u]]);export{x as __pageData,C as default};
